#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps GC from collecting it (packaged crash in AddPoints).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* without UPROPERTY, so nothing keeps the NewObject alive; garbage collection frees it after about a minute and OnGoalScored -> AddPoints reads freed memory (EXCEPTION_ACCESS_VIOLATION at ArenaScoreTracker.cpp:18). Fixed by making it UPROPERTY() TObjectPtr.",
  "no_colors_cause": "DA_Primary is only loaded at runtime by string path (LoadObject), so the cooker sees no reference and leaves /Game/Data/Palettes out of the packaged build (log: Couldn't find file for package /Game/Data/Palettes/DA_Primary, Palette is null, using fallback gray). Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
